/**
 * Which state or territory a coordinate falls in.
 *
 * Used to tag archived incidents so the logs page can filter by one.
 * Most sources are NSW-only, but the national ones (LiveTraffic works,
 * FIRMS hotspots) and ACT Ambulance span several, and nothing upstream
 * reliably says which - the coordinate is the only trustworthy signal.
 *
 * Rings come from the ArcGIS "State Boundaries" service, per
 * jurisdiction, queried at maxAllowableOffset=0.0005 (~55 m) and then
 * simplified to 0.002 deg (~220 m), with slivers under ~1 km2 dropped.
 *
 * THE QUERY OFFSET MATTERS MORE THAN THE SIMPLIFY. An earlier build
 * queried at maxAllowableOffset=0.01 (~1.1 km), which threw the border
 * detail away before any local simplification could preserve it: the ACT
 * came back as a 20-point blob that bulged east over Queanbeyan, and the
 * Murray River border drifted far enough to put Moama and Barham in
 * Victoria. Re-querying at 55 m fixed all of those. Going finer than
 * 0.002 on the simplify buys nothing measurable - across 3,000 real
 * archived coordinates, 0.002 / 0.001 / 0.0005 agreed on every single
 * point, at a third of the bytes.
 *
 * Unlike lib/australiaMask.ts these rings are NOT buffered outward:
 * buffering would make neighbouring states overlap and a point near a
 * border could land in either. Interior borders stay sharp, and coastal
 * slop is handled by the fallback below instead.
 *
 * Two passes:
 *   1. exact point-in-polygon - the answer for anything on land;
 *   2. nearest boundary within 0.12 deg (~13 km) - catches a record just
 *      offshore and attributes it to the coast it sits against.
 * Anything further out returns null, which the logs page shows as an
 * unknown state rather than guessing.
 *
 * 44937 vertices. Regenerating: re-query the service at that offset, union
 * per state, simplify, re-emit.
 */

export type AuState = 'NSW' | 'VIC' | 'QLD' | 'SA' | 'WA' | 'TAS' | 'NT' | 'ACT';

/** Display order - most populous first, territories last. */
export const AU_STATES: readonly AuState[] = ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'];

/**
 * Order the rings are TESTED in, which is not the display order.
 *
 * Only exterior rings are stored, so an enclave is contained by the ring
 * of the state around it: every ACT coordinate also falls inside the NSW
 * exterior. Testing the enclave first resolves that - Canberra answers
 * ACT, and a point in NSW is unaffected because it was never inside the
 * ACT ring to begin with.
 *
 * (Jervis Bay is the other hole in NSW. It is an external territory, not
 * one of the eight, so it has no rings here and resolves to the NSW that
 * surrounds it - the useful answer for a logs filter.)
 */
const RESOLVE_ORDER: readonly AuState[] = ['ACT', 'NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT'];

/** How far offshore a point may sit and still be attributed (degrees). */
const COAST_TOLERANCE_DEG = 0.12;

type Ring = ReadonlyArray<readonly [number, number]>;

