/** Per-ring bounding boxes, so most rings are skipped without a scan. */
const STATE_BOXES: Record<AuState, Array<readonly [number, number, number, number]>> =
  Object.fromEntries(
    (Object.keys(STATE_RINGS) as AuState[]).map((ab) => [
      ab,
      STATE_RINGS[ab].map((r) => {
        let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
        for (const [x, y] of r) {
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
        return [x0, y0, x1, y1] as const;
      }),
    ]),
  ) as Record<AuState, Array<readonly [number, number, number, number]>>;

function pointInRing(ring: Ring, lon: number, lat: number): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const a = ring[i]!, b = ring[j]!;
    const xi = a[0], yi = a[1], xj = b[0], yj = b[1];
    if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}

/** Distance from a point to a segment, in degrees (planar - fine at this scale). */
function distToSegment(
  px: number, py: number, ax: number, ay: number, bx: number, by: number,
): number {
  const dx = bx - ax, dy = by - ay;
  if (dx === 0 && dy === 0) return Math.hypot(px - ax, py - ay);
  let t = ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy);
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}

/**
 * The state/territory containing this coordinate, or null when it is not
 * in (or close enough to) any of them - open ocean, or another country.
 */
export function stateForPoint(lon: number, lat: number): AuState | null {
  if (!Number.isFinite(lon) || !Number.isFinite(lat)) return null;

  for (const ab of RESOLVE_ORDER) {
    const rings = STATE_RINGS[ab], boxes = STATE_BOXES[ab];
    for (let i = 0; i < rings.length; i++) {
      const b = boxes[i]!;
      if (lon < b[0] || lon > b[2] || lat < b[1] || lat > b[3]) continue;
      if (pointInRing(rings[i]!, lon, lat)) return ab;
    }
  }

  const tol = COAST_TOLERANCE_DEG;
  let best: AuState | null = null;
  let bestDist = tol;
  for (const ab of RESOLVE_ORDER) {
    const rings = STATE_RINGS[ab], boxes = STATE_BOXES[ab];
    for (let i = 0; i < rings.length; i++) {
      const b = boxes[i]!;
      if (lon < b[0] - tol || lon > b[2] + tol || lat < b[1] - tol || lat > b[3] + tol) continue;
      const r = rings[i]!;
      for (let j = 0; j < r.length - 1; j++) {
        const p = r[j]!, q = r[j + 1]!;
        const d = distToSegment(lon, lat, p[0], p[1], q[0], q[1]);
        if (d < bestDist) { bestDist = d; best = ab; }
      }
    }
  }
  return best;
}

/**
 * Pull a coordinate out of an archived row and resolve its state.
 *
 * Sources disagree on spelling: traffic/rfs/firms/act use lat+lng, the
 * power feeds use latitude+longitude. Returns null when the row carries
 * no usable point (BOM warnings are areas, not points).
 */
export function stateForRow(data: unknown): AuState | null {
  if (!data || typeof data !== 'object') return null;
  const d = data as Record<string, unknown>;
  const num = (v: unknown): number | null => {
    if (typeof v === 'number') return Number.isFinite(v) ? v : null;
    if (typeof v === 'string' && v.trim() !== '') {
      const n = Number(v);
      return Number.isFinite(n) ? n : null;
    }
    return null;
  };
  const lat = num(d['lat']) ?? num(d['latitude']);
  const lon = num(d['lng']) ?? num(d['longitude']) ?? num(d['lon']);
  if (lat === null || lon === null) return null;
  return stateForPoint(lon, lat);
}
